/**
 * Локальные демо-JPEG без интернета (цветные плейсхолдеры через sharp-free SVG→не, просто копии разных цветов)
 * На самом деле — минимальный валидный JPEG 120x120 из canvas через pure node - use fixed buffers.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const outDir = path.join(__dirname, '..', 'prisma', 'seed-assets', 'products');

/** Маленькие валидные JPEG (разные оттенки), base64 */
const images = {
  'grechka.jpg':
    '',
  'condensed-milk.jpg':
    '',
  'laundry-powder.jpg':
    '',
  'paracetamol.jpg':
    '',
  'sealant.jpg':
    '',
};

await mkdir(outDir, { recursive: true });

for (const [file, b64] of Object.entries(images)) {
  await writeFile(path.join(outDir, file), Buffer.from(b64, 'base64'));
  console.log('OK', file);
}

console.log(`Generated in ${outDir}`);
